<?php
declare(strict_types=1); require dirname(__DIR__,1).'/vendor/autoload.php'; $app=new think\App(dirname(__DIR__,1));$app->initialize(); use think\facade\Db;
$map3=[2=>150,3=>50,4=>25,5=>15,6=>10,7=>7.142,8=>5.3,9=>4.166,10=>3.3];$map6=[3=>150,4=>37,5=>15,6=>7.5,7=>4.285,8=>2.678,9=>1.785,10=>1.2];
Db::transaction(function()use($map3,$map6):void{
 $rows=Db::name('bet_details')->alias('d')->leftJoin('user_stop_drops s','s.bet_detail_id=d.id')->where(function($q){$q->where('d.source_text','like','%组三%')->whereOr('d.source_text','like','%组六%');})->field('d.id,d.number_text,d.odds,d.source_text,s.play_type')->select()->toArray();
 foreach($rows as $row){$src=(string)$row['source_text']; if(str_contains($src,'组三赖')||str_contains($src,'组六赖'))continue; $prefix=''; if(preg_match('/([0-9]{4,10})\s*组六/u',$src,$m)){$n=count(array_unique(str_split($m[1])));$expected=$map6[$n]??null;$label=$n===10?'组六全包':'组六'.(['4'=>'四','5'=>'五','6'=>'六','7'=>'七','8'=>'八','9'=>'九'][$n]??$n).'码';$prefix='六';}elseif(preg_match('/([0-9]{4,10})\s*组三/u',$src,$m)){$n=count(array_unique(str_split($m[1])));$expected=$map3[$n]??null;$label=$n===10?'组三全包':'组三'.(['2'=>'两','3'=>'三','4'=>'四','5'=>'五','6'=>'六','7'=>'七','8'=>'八','9'=>'九'][$n]??$n).'码';$prefix='三';}else continue;if($expected===null||abs((float)$row['odds']-$expected)<0.0005)continue;$newSource=$m[1].' '.$label.' '.(str_contains($src,'体')?'体':'福');Db::name('bet_details')->where('id',(int)$row['id'])->update(['odds'=>number_format($expected,3,'.',''),'source_text'=>$newSource,'number_text'=>$prefix.$m[1]]);Db::name('user_stop_drops')->where('bet_detail_id',(int)$row['id'])->update(['play_type'=>$label,'original_odds'=>number_format($expected,3,'.',''),'actual_odds'=>number_format($expected,3,'.',''),'source_text'=>$newSource]);}
}); echo "all group odds repair completed\n";
